function LiveCatalog({ filter }: { filter: Category }) {
  const [courses, setCourses] = useState<Course[]>([]);
  // ...initial fetch for filter...
  useEffect(() => {
    const id = setInterval(() => {
      fetchCourses(filter).then(setCourses);
    }, 30_000);
    return () => clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  // ...
}

API log for one tab (the learner switched from React to Node at 10:00:12):
10:00:00 GET /courses?category=react 200
10:00:12 GET /courses?category=node 200
10:00:30 GET /courses?category=react 200

Statement: "The 10:00:30 request asks for react because the interval callback was created in the first render and still reads the filter value of that render."

A reviewer suggests this change to the same effect, keeping the empty dependency array:

useEffect(() => {
  const id = setInterval(() => {
    fetchCourses(filter).then((fresh) => setCourses((prev) => (sameIds(prev, fresh) ? prev : fresh)));
  }, 30_000);
  return () => clearInterval(id);
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, []);

Statement: "Because the update now uses the functional form setCourses((prev) => ...), the refresh will request the category the learner selected last."
